 267→func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
 268→	settings, err := LoadEntireSettings(ctx)
 269→	if err != nil {
 270→		return fmt.Errorf("failed to load settings: %w", err)
 271→	}
