 294→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 295→// Returns true if the caller should exit (i.e., Entire is disabled).
 296→// On error reading settings, defaults to enabled (returns false).
 297→func checkDisabledGuard(ctx context.Context, w io.Writer) bool {
 298→	enabled, err := IsEnabled(ctx)
