 522→// canPromptInteractively checks if we can show interactive prompts.
 523→// Returns false when running in CI, tests, or other non-interactive environments.
 524→func canPromptInteractively() bool {
 525→	// Check for test environment
 526→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 527→		return os.Getenv("ENTIRE_TEST_TTY") == "1"
 528→	}
 529→
 530→	// Check if /dev/tty is available
 531→	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 532→	if err != nil {
 533→		return false
 534→	}
 535→	_ = tty.Close()
 536→	return true
 537→}
