1023→// countSessionStates returns the number of active session state files.
1024→func countSessionStates(ctx context.Context) int {
1025→	store, err := session.NewStateStore(ctx)
1026→	if err != nil {
1027→		return 0
1028→	}
1029→	states, err := store.List(ctx)
1030→	if err != nil {
1031→		return 0
1032→	}
1033→	return len(states)
1034→}
1035→
1036→// countShadowBranches returns the number of shadow branches.
1037→func countShadowBranches(ctx context.Context) int {
1038→	branches, err := strategy.ListShadowBranches(ctx)
1039→	if err != nil {
1040→		return 0
1041→	}
1042→	return len(branches)
1043→}
1044→
1045→// checkEntireDirExists checks if the .entire directory exists.
1046→func checkEntireDirExists(ctx context.Context) bool {
1047→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1048→	if err != nil {
1049→		entireDirAbs = paths.EntireDir
1050→	}
1051→	_, err = os.Stat(entireDirAbs)
1052→	return err == nil
1053→}
1054→
1055→// removeAgentHooks removes hooks from all agents that support hooks.
1056→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1057→	var errs []error
1058→	for _, name := range agent.List() {
1059→		ag, err := agent.Get(name)
1060→		if err != nil {
1061→			continue
1062→		}
1063→		hs, ok := ag.(agent.HookSupport)
1064→		if !ok {
1065→			continue
1066→		}
1067→		wasInstalled := hs.AreHooksInstalled(ctx)
1068→		if err := hs.UninstallHooks(ctx); err != nil {
1069→			errs = append(errs, err)
1070→		} else if wasInstalled {
1071→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1072→		}
1073→	}
1074→	return errors.Join(errs...)
1075→}
1076→
1077→// removeAllSessionStates removes all session state files and the directory.
1078→func removeAllSessionStates(ctx context.Context) (int, error) {
1079→	store, err := session.NewStateStore(ctx)
1080→	if err != nil {
1081→		return 0, fmt.Errorf("failed to create state store: %w", err)
1082→	}
1083→
1084→	// Count states before removing
1085→	states, err := store.List(ctx)
1086→	if err != nil {
1087→		return 0, fmt.Errorf("failed to list session states: %w", err)
1088→	}
1089→	count := len(states)
1090→
1091→	// Remove the entire directory
1092→	if err := store.RemoveAll(); err != nil {
1093→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1094→	}
1095→
1096→	return count, nil
1097→}
1098→
1099→// removeEntireDirectory removes the .entire directory.
1100→func removeEntireDirectory(ctx context.Context) error {
1101→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1102→	if err != nil {
1103→		entireDirAbs = paths.EntireDir
1104→	}
1105→	if err := os.RemoveAll(entireDirAbs); err != nil {
1106→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1107→	}
1108→	return nil
1109→}
1110→
1111→// removeAllShadowBranches removes all shadow branches.
1112→func removeAllShadowBranches(ctx context.Context) (int, error) {
1113→	branches, err := strategy.ListShadowBranches(ctx)
1114→	if err != nil {
1115→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
1116→	}
1117→	if len(branches) == 0 {
1118→		return 0, nil
1119→	}
1120→	deleted, _, err := strategy.DeleteShadowBranches(ctx, branches)
1121→	return len(deleted), err
1122→}
