 27→func TestSessionStruct(t *testing.T) {
 28→	now := time.Now()
 29→	checkpoints := []Checkpoint{
 30→		{
 31→			CheckpointID:     id.MustCheckpointID("abc123def456"),
 32→			Message:          "First checkpoint",
