 40→			Timestamp:        now,
 41→			IsTaskCheckpoint: true,
 42→			ToolUseID:        "toolu_123",
 43→		},
 44→	}
 45→
 46→	session := Session{
 47→		ID:          "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e",
 48→		Description: "Fix lint errors",
 49→		Strategy:    StrategyNameManualCommit,
 50→		StartTime:   now.Add(-2 * time.Hour),
 51→		Checkpoints: checkpoints,
 52→	}
 53→
 54→	if session.ID != "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e" {
 55→		t.Errorf("expected session ID to match, got %s", session.ID)
 56→	}
 57→	if session.Description != "Fix lint errors" {
 58→		t.Errorf("expected description to match, got %s", session.Description)
 59→	}
 60→	if session.Strategy != StrategyNameManualCommit {
 61→		t.Errorf("expected strategy to be manual-commit, got %s", session.Strategy)
 62→	}
 63→	if len(session.Checkpoints) != 2 {
 64→		t.Errorf("expected 2 checkpoints, got %d", len(session.Checkpoints))
 65→	}
 66→	if session.StartTime.IsZero() {
 67→		t.Error("expected StartTime to be set")
 68→	}
 69→}
