 71→func TestCheckpointStruct(t *testing.T) {
 72→	now := time.Now()
 73→
 74→	// Test session checkpoint (not task)
 75→	sessionCheckpoint := Checkpoint{
 76→		CheckpointID:     "abc1234567890",
 77→		Message:          "Session save",
 78→		Timestamp:        now,
 79→		IsTaskCheckpoint: false,
 80→		ToolUseID:        "",
 81→	}
 82→
 83→	if sessionCheckpoint.CheckpointID != "abc1234567890" {
 84→		t.Errorf("expected CheckpointID to match, got %s", sessionCheckpoint.CheckpointID)
 85→	}
 86→	if sessionCheckpoint.Message != "Session save" {
 87→		t.Errorf("expected Message to match, got %s", sessionCheckpoint.Message)
 88→	}
 89→	if sessionCheckpoint.Timestamp != now {
 90→		t.Error("expected Timestamp to match")
 91→	}
 92→	if sessionCheckpoint.IsTaskCheckpoint {
 93→		t.Error("expected session checkpoint to not be a task checkpoint")
 94→	}
 95→	if sessionCheckpoint.ToolUseID != "" {
 96→		t.Error("expected session checkpoint to have empty ToolUseID")
 97→	}
 98→
 99→	// Test task checkpoint
100→	taskCheckpoint := Checkpoint{
101→		CheckpointID:     "def0987654321",
102→		Message:          "Task: implement feature",
103→		Timestamp:        now,
104→		IsTaskCheckpoint: true,
105→		ToolUseID:        "toolu_abc123",
106→	}
107→
108→	if taskCheckpoint.CheckpointID != "def0987654321" {
109→		t.Errorf("expected CheckpointID to match, got %s", taskCheckpoint.CheckpointID)
110→	}
111→	if taskCheckpoint.Message != "Task: implement feature" {
112→		t.Errorf("expected Message to match, got %s", taskCheckpoint.Message)
113→	}
114→	if taskCheckpoint.Timestamp != now {
115→		t.Error("expected Timestamp to match")
116→	}
117→	if !taskCheckpoint.IsTaskCheckpoint {
118→		t.Error("expected task checkpoint to be a task checkpoint")
119→	}
120→	if taskCheckpoint.ToolUseID != "toolu_abc123" {
121→		t.Errorf("expected ToolUseID to match, got %s", taskCheckpoint.ToolUseID)
122→	}
123→}
