	if err != nil {
		t.Fatalf("saveSessionState() error = %v", err)
	}

	// Verify file exists
	stateFile := filepath.Join(".git", "entire-sessions", "test-session-123.json")
	if _, err := os.Stat(stateFile); os.IsNotExist(err) {
