	}

	// Verify session state now has a valid BaseCommit
	loaded, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("failed to load session state: %v", err)
	}
	if loaded.BaseCommit == "" {
