 25→// Commit linking mode constants.
 26→const (
 27→	// CommitLinkingAlways auto-links commits to sessions without prompting.
 28→	CommitLinkingAlways = "always"
 29→	// CommitLinkingPrompt prompts the user on each commit (default for existing users).
 30→	CommitLinkingPrompt = "prompt"
 31→)
 32→
 33→// EntireSettings represents the .entire/settings.json configuration
 34→type EntireSettings struct {
 35→
 36→	// Enabled indicates whether Entire is active. When false, CLI commands
 37→	// show a disabled message and hooks exit silently. Defaults to true.
 38→	Enabled bool `json:"enabled"`
 39→
 40→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
 41→	// This is used for development when the binary is not installed
 42→	LocalDev bool `json:"local_dev,omitempty"`
 43→
 44→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 45→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 46→	// Defaults to "info".
 47→	LogLevel string `json:"log_level,omitempty"`
 48→
 49→	// StrategyOptions contains strategy-specific configuration
 50→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 51→
 52→	// Telemetry controls anonymous usage analytics.
 53→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 54→	Telemetry *bool `json:"telemetry,omitempty"`
 55→
 56→	// CommitLinking controls how commits are linked to agent sessions.
 57→	// "always" = auto-link without prompting, "prompt" = ask on each commit.
 58→	// Defaults to "prompt" (preserves existing user behavior).
 59→	CommitLinking string `json:"commit_linking,omitempty"`
 60→
 61→	// Deprecated: no longer used. Exists to tolerate old settings files
 62→	// that still contain "strategy": "auto-commit" or similar.
 63→	Strategy string `json:"strategy,omitempty"`
 64→}
 65→
 66→// GetCommitLinking returns the effective commit linking mode.
 67→// Returns the explicit value if set, otherwise defaults to "prompt"
 68→// to preserve existing user behavior.
 69→func (s *EntireSettings) GetCommitLinking() string {
 70→	if s.CommitLinking != "" {
 71→		return s.CommitLinking
 72→	}
 73→	return CommitLinkingPrompt
 74→}
 75→
 76→// Load loads the Entire settings from .entire/settings.json,
 77→// then applies any overrides from .entire/settings.local.json if it exists.
 78→// Returns default settings if neither file exists.
 79→// Works correctly from any subdirectory within the repository.
 80→func Load(ctx context.Context) (*EntireSettings, error) {
 81→	// Get absolute paths for settings files
 82→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 83→	if err != nil {
 84→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 85→	}
 86→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 87→	if err != nil {
 88→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 89→	}
 90→
 91→	// Load base settings
 92→	settings, err := loadFromFile(settingsFileAbs)
 93→	if err != nil {
 94→		return nil, fmt.Errorf("reading settings file: %w", err)
 95→	}
 96→
 97→	// Apply local overrides if they exist
 98→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
 99→	if err != nil {
100→		if !os.IsNotExist(err) {
101→			return nil, fmt.Errorf("reading local settings file: %w", err)
102→		}
103→		// Local file doesn't exist, continue without overrides
104→	} else {
105→		if err := mergeJSON(settings, localData); err != nil {
106→			return nil, fmt.Errorf("merging local settings: %w", err)
107→		}
108→	}
109→
110→	return settings, nil
111→}
112→
113→// LoadFromFile loads settings from a specific file path without merging local overrides.
114→// Returns default settings if the file doesn't exist.
115→// Use this when you need to display individual settings files separately.
116→func LoadFromFile(filePath string) (*EntireSettings, error) {
117→	return loadFromFile(filePath)
118→}
119→
120→// loadFromFile loads settings from a specific file path.
121→// Returns default settings if the file doesn't exist.
122→func loadFromFile(filePath string) (*EntireSettings, error) {
123→	settings := &EntireSettings{
124→		Enabled: true, // Default to enabled
125→	}
126→
127→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
128→	if err != nil {
129→		if os.IsNotExist(err) {
130→			return settings, nil
131→		}
132→		return nil, fmt.Errorf("%w", err)
133→	}
134→
135→	dec := json.NewDecoder(bytes.NewReader(data))
136→	dec.DisallowUnknownFields()
137→	if err := dec.Decode(settings); err != nil {
138→		return nil, fmt.Errorf("parsing settings file: %w", err)
139→	}
140→
141→	// Validate commit_linking if set
142→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
143→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
144→	}
145→
146→	return settings, nil
147→}
148→
149→// mergeJSON merges JSON data into existing settings.
150→// Only non-zero values from the JSON override existing settings.
151→func mergeJSON(settings *EntireSettings, data []byte) error {
152→	// First, validate that there are no unknown keys using strict decoding
153→	dec := json.NewDecoder(bytes.NewReader(data))
154→	dec.DisallowUnknownFields()
155→	var temp EntireSettings
156→	if err := dec.Decode(&temp); err != nil {
157→		return fmt.Errorf("parsing JSON: %w", err)
158→	}
159→
160→	// Parse into a map to check which fields are present
161→	var raw map[string]json.RawMessage
162→	if err := json.Unmarshal(data, &raw); err != nil {
163→		return fmt.Errorf("parsing JSON: %w", err)
164→	}
165→
166→	// Override enabled if present
167→	if enabledRaw, ok := raw["enabled"]; ok {
168→		var e bool
169→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
170→			return fmt.Errorf("parsing enabled field: %w", err)
171→		}
172→		settings.Enabled = e
173→	}
174→
175→	// Override local_dev if present
176→	if localDevRaw, ok := raw["local_dev"]; ok {
177→		var ld bool
178→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
179→			return fmt.Errorf("parsing local_dev field: %w", err)
180→		}
181→		settings.LocalDev = ld
182→	}
183→
184→	// Override log_level if present and non-empty
185→	if logLevelRaw, ok := raw["log_level"]; ok {
186→		var ll string
187→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
188→			return fmt.Errorf("parsing log_level field: %w", err)
189→		}
190→		if ll != "" {
191→			settings.LogLevel = ll
192→		}
193→	}
194→
195→	// Merge strategy_options if present
196→	if optionsRaw, ok := raw["strategy_options"]; ok {
197→		var opts map[string]any
198→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
199→			return fmt.Errorf("parsing strategy_options field: %w", err)
200→		}
201→		if settings.StrategyOptions == nil {
202→			settings.StrategyOptions = opts
203→		} else {
204→			for k, v := range opts {
205→				settings.StrategyOptions[k] = v
206→			}
207→		}
208→	}
209→
210→	// Override telemetry if present
211→	if telemetryRaw, ok := raw["telemetry"]; ok {
212→		var t bool
213→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
214→			return fmt.Errorf("parsing telemetry field: %w", err)
215→		}
216→		settings.Telemetry = &t
217→	}
218→
219→	// Override commit_linking if present and non-empty
220→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
221→		var cl string
222→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
223→			return fmt.Errorf("parsing commit_linking field: %w", err)
224→		}
225→		if cl != "" {
226→			switch cl {
227→			case CommitLinkingAlways, CommitLinkingPrompt:
228→				settings.CommitLinking = cl
229→			default:
230→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
231→			}
232→		}
233→	}
234→
235→	return nil
236→}
