238→// IsSetUp returns true if Entire has been set up in the current repository.
239→// This checks if .entire/settings.json exists.
240→// Use this to avoid creating files/directories in repos where Entire was never enabled.
241→func IsSetUp(ctx context.Context) bool {
242→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
243→	if err != nil {
244→		return false
245→	}
246→	_, err = os.Stat(settingsFileAbs)
247→	return err == nil
248→}
249→
250→// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
251→// This checks if .entire/settings.json exists AND has enabled: true.
252→// Use this for hooks that should be no-ops when Entire is not active.
253→func IsSetUpAndEnabled(ctx context.Context) bool {
254→	if !IsSetUp(ctx) {
255→		return false
256→	}
257→	s, err := Load(ctx)
258→	if err != nil {
259→		return false
260→	}
261→	return s.Enabled
262→}
263→
264→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
265→// Returns false by default if settings cannot be loaded or the key is missing.
266→func IsSummarizeEnabled(ctx context.Context) bool {
267→	settings, err := Load(ctx)
268→	if err != nil {
269→		return false
270→	}
271→	return settings.IsSummarizeEnabled()
272→}
273→
274→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
275→func (s *EntireSettings) IsSummarizeEnabled() bool {
276→	if s.StrategyOptions == nil {
277→		return false
278→	}
279→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
280→	if !ok {
281→		return false
282→	}
283→	enabled, ok := summarizeOpts["enabled"].(bool)
284→	if !ok {
285→		return false
286→	}
287→	return enabled
288→}
289→
290→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
291→// Returns true if push_sessions is explicitly set to false.
292→func (s *EntireSettings) IsPushSessionsDisabled() bool {
293→	if s.StrategyOptions == nil {
294→		return false
295→	}
296→	val, exists := s.StrategyOptions["push_sessions"]
297→	if !exists {
298→		return false
299→	}
300→	if boolVal, ok := val.(bool); ok {
301→		return !boolVal // disabled = !push_sessions
302→	}
303→	return false
304→}
305→
306→// Save saves the settings to .entire/settings.json.
307→func Save(ctx context.Context, settings *EntireSettings) error {
308→	return saveToFile(ctx, settings, EntireSettingsFile)
309→}
310→
311→// SaveLocal saves the settings to .entire/settings.local.json.
312→func SaveLocal(ctx context.Context, settings *EntireSettings) error {
313→	return saveToFile(ctx, settings, EntireSettingsLocalFile)
314→}
315→
316→// saveToFile saves settings to the specified file path.
317→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
318→	// Get absolute path for the file
319→	filePathAbs, err := paths.AbsPath(ctx, filePath)
320→	if err != nil {
321→		filePathAbs = filePath // Fallback to relative
322→	}
323→
324→	// Ensure directory exists
325→	dir := filepath.Dir(filePathAbs)
326→	if err := os.MkdirAll(dir, 0o750); err != nil {
327→		return fmt.Errorf("creating settings directory: %w", err)
328→	}
329→
330→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
331→	if err != nil {
332→		return fmt.Errorf("marshaling settings: %w", err)
333→	}
334→
335→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
336→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
337→		return fmt.Errorf("writing settings file: %w", err)
338→	}
339→	return nil
340→}
