1090→// countSessionStates returns the number of active session state files.
1091→func countSessionStates(ctx context.Context) int {
1092→	store, err := session.NewStateStore(ctx)
1093→	if err != nil {
1094→		return 0
1095→	}
1096→	states, err := store.List(ctx)
1097→	if err != nil {
1098→		return 0
1099→	}
1100→	return len(states)
1101→}
