1122→// removeAgentHooks removes hooks from all agents that support hooks.
1123→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1124→	var errs []error
1125→	for _, name := range agent.List() {
1126→		ag, err := agent.Get(name)
1127→		if err != nil {
1128→			continue
1129→		}
1130→		hs, ok := ag.(agent.HookSupport)
1131→		if !ok {
1132→			continue
1133→		}
1134→		wasInstalled := hs.AreHooksInstalled(ctx)
1135→		if err := hs.UninstallHooks(ctx); err != nil {
1136→			errs = append(errs, err)
1137→		} else if wasInstalled {
1138→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1139→		}
1140→	}
1141→	return errors.Join(errs...)
1142→}
1143→
1144→// removeAllSessionStates removes all session state files and the directory.
1145→func removeAllSessionStates(ctx context.Context) (int, error) {
1146→	store, err := session.NewStateStore(ctx)
1147→	if err != nil {
1148→		return 0, fmt.Errorf("failed to create state store: %w", err)
1149→	}
1150→
1151→	// Count states before removing
1152→	states, err := store.List(ctx)
1153→	if err != nil {
1154→		return 0, fmt.Errorf("failed to list session states: %w", err)
1155→	}
1156→	count := len(states)
1157→
1158→	// Remove the entire directory
1159→	if err := store.RemoveAll(); err != nil {
1160→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1161→	}
1162→
1163→	return count, nil
1164→}
1165→
1166→// removeEntireDirectory removes the .entire directory.
1167→func removeEntireDirectory(ctx context.Context) error {
1168→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1169→	if err != nil {
1170→		entireDirAbs = paths.EntireDir
1171→	}
1172→	if err := os.RemoveAll(entireDirAbs); err != nil {
1173→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1174→	}
1175→	return nil
1176→}
