1178→// removeAllShadowBranches removes all shadow branches.
1179→func removeAllShadowBranches(ctx context.Context) (int, error) {
1180→	branches, err := strategy.ListShadowBranches(ctx)
1181→	if err != nil {
1182→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
1183→	}
1184→	if len(branches) == 0 {
1185→		return 0, nil
1186→	}
1187→	deleted, _, err := strategy.DeleteShadowBranches(ctx, branches)
1188→	return len(deleted), err
1189→}
