 63→func askConfirmTTY(prompt string, context string, defaultYes bool) bool {
 64→	// In test mode, don't try to interact with the real TTY — just use the default.
 65→	// ENTIRE_TEST_TTY=1 simulates "a human is present" for the hasTTY() check
 66→	// but we can't actually read from the TTY in tests.
 67→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 68→		return defaultYes
 69→	}
 70→
 71→	// Gemini CLI sets GEMINI_CLI=1 when running shell commands (including git commit).
 72→	// The agent can't respond to TTY prompts, so use the default to avoid hanging.
 73→	// See: https://geminicli.com/docs/tools/shell/
 74→	if os.Getenv("GEMINI_CLI") != "" {
 75→		return defaultYes
