103→	reader := bufio.NewReader(tty)
104→	response, err := reader.ReadString('\n')
105→	if err != nil {
106→		return defaultYes
107→	}
108→
109→	response = strings.TrimSpace(strings.ToLower(response))
110→	switch response {
111→	case "y", "yes":
112→		return true
113→	case "n", "no":
114→		return false
115→	default:
116→		// Empty or invalid input - use default
117→		return defaultYes
118→	}
119→}
