1429→func addCheckpointTrailer(message string, checkpointID id.CheckpointID) string {
1430→	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
1431→
1432→	// If message already ends with trailers (lines starting with key:), just append
1433→	// Otherwise, add a blank line first
1434→	lines := strings.Split(strings.TrimRight(message, "\n"), "\n")
1435→
1436→	// Check if the message already ends with a trailer paragraph.
1437→	// Git trailers must be in a separate paragraph (preceded by a blank line).
1438→	// A single-paragraph message (e.g., just a subject line) cannot have trailers,
1439→	// even if the subject contains ": " (like conventional commits: "docs: Add foo").
1440→	//
1441→	// Scan from the bottom: find the last paragraph of non-comment content,
1442→	// then check if it looks like trailers AND has a blank line above it.
1443→	hasTrailers := false
1444→	i := len(lines) - 1
1445→
1446→	// Skip trailing comment lines
1447→	for i >= 0 && strings.HasPrefix(strings.TrimSpace(lines[i]), "#") {
1448→		i--
1449→	}
1450→
1451→	// Check if the last non-comment line looks like a trailer
1452→	if i >= 0 {
1453→		line := strings.TrimSpace(lines[i])
1454→		if line != "" && strings.Contains(line, ": ") {
1455→			// Found a trailer-like line. Now scan upward past the trailer block
1456→			// to verify there's a blank line (paragraph separator) above it.
1457→			for i > 0 {
1458→				i--
1459→				above := strings.TrimSpace(lines[i])
1460→				if strings.HasPrefix(above, "#") {
1461→					continue
1462→				}
1463→				if above == "" {
1464→					// Blank line found above trailer block — real trailers
1465→					hasTrailers = true
1466→					break
1467→				}
1468→				if !strings.Contains(above, ": ") {
1469→					// Non-trailer, non-blank line — this is message body, not trailers
1470→					break
1471→				}
1472→				// Another trailer-like line, keep scanning upward
1473→			}
1474→		}
1475→	}
1476→
1477→	if hasTrailers {
1478→		// Append trailer directly
1479→		return strings.TrimRight(message, "\n") + "\n" + trailer + "\n"
1480→	}
1481→
1482→	// Add blank line before trailer
1483→	return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n"
1484→}
1485→
1486→// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer with an explanatory comment.
1487→// The trailer is placed above the git comment block but below the user's message area,
1488→// with a comment explaining that the user can remove it if they don't want to link the commit
1489→// to the agent session. If prompt is non-empty, it's shown as context.
1490→func addCheckpointTrailerWithComment(message string, checkpointID id.CheckpointID, agentName, prompt string) string {
1491→	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
1492→	commentLines := []string{
1493→		"# Remove the Entire-Checkpoint trailer above if you don't want to link this commit to " + agentName + " session context.",
1494→	}
1495→	if prompt != "" {
1496→		commentLines = append(commentLines, "# Last Prompt: "+prompt)
1497→	}
1498→	commentLines = append(commentLines, "# The trailer will be added to your next commit based on this branch.")
1499→	comment := strings.Join(commentLines, "\n")
1500→
1501→	lines := strings.Split(message, "\n")
1502→
1503→	// Find where the git comment block starts (first # line)
1504→	commentStart := -1
1505→	for i, line := range lines {
1506→		if strings.HasPrefix(line, "#") {
1507→			commentStart = i
1508→			break
1509→		}
1510→	}
1511→
1512→	if commentStart == -1 {
1513→		// No git comments, append trailer at the end
1514→		return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n" + comment + "\n"
1515→	}
1516→
1517→	// Split into user content and git comments
1518→	userContent := strings.Join(lines[:commentStart], "\n")
1519→	gitComments := strings.Join(lines[commentStart:], "\n")
1520→
1521→	// Build result: user content, blank line, trailer, comment, blank line, git comments
1522→	userContent = strings.TrimRight(userContent, "\n")
1523→	if userContent == "" {
1524→		// No user content yet - leave space for them to type, then trailer
1525→		// Two newlines: first for user's message line, second for blank separator
1526→		return "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
1527→	}
1528→	return userContent + "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments

