 726→// migrateProjectSettings loads the project settings.json directly,
 727→// clears the deprecated strategy field, sets commit_linking if missing,
 728→// and saves it back. This is needed when the main save goes to
 729→// settings.local.json — the project file still needs cleanup.
 730→func migrateProjectSettings(ctx context.Context) error {
 731→	settingsFileAbs, err := paths.AbsPath(ctx, settings.EntireSettingsFile)
