1103→// countShadowBranches returns the number of shadow branches.
1104→func countShadowBranches(ctx context.Context) int {
1105→	branches, err := strategy.ListShadowBranches(ctx)
1106→	if err != nil {
1107→		return 0
1108→	}
1109→	return len(branches)
