113→// LoadFromFile loads settings from a specific file path without merging local overrides.
114→// Returns default settings if the file doesn't exist.
115→// Use this when you need to display individual settings files separately.
116→func LoadFromFile(filePath string) (*EntireSettings, error) {
117→	return loadFromFile(filePath)
118→}
